{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1113;--card:#0b0c0d;--muted:#9aa4a8;--accent:#7ad3c8;--glass:rgba(255,255,255,0.03);--maxw:980px}
    *{box-sizing:border-box}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#e6f6f2;background:linear-gradient(180deg,#071718 0%,#081a1b 40%),url('assets/img/pattern.svg');background-size:450px;line-height:1.45}
    header{backdrop-filter:blur(6px);background:linear-gradient(180deg,rgba(0,0,0,0.2),transparent);padding:18px 24px;position:sticky;top:0;z-index:60;border-bottom:1px solid rgba(255,255,255,0.03)}
    nav{max-width:var(--maxw);margin:0 auto;display:flex;gap:12px;align-items:center}
    .brand{font-weight:600;color:var(--accent);letter-spacing:0.2px}
    .navlinks{margin-left:auto;display:flex;gap:14px}
    .navlinks a{color:#cdeae6;text-decoration:none;padding:8px 12px;border-radius:8px;font-size:14px}
    .navlinks a:hover{background:rgba(122,211,200,0.06)}
    .container{max-width:var(--maxw);margin:40px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:center}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:22px;border-radius:14px;box-shadow:0 6px 20px rgba(2,6,7,0.6);border:1px solid rgba(255,255,255,0.03)}
    h1{margin:0 0 10px;font-size:28px}
    p.lead{margin:0;color:var(--muted)}
    .actions{display:flex;gap:10px;margin-top:14px}
    .btn{display:inline-flex;align-items:center;gap:10px;border:none;padding:10px 14px;border-radius:10px;font-weight:600;cursor:pointer}
    .btn-primary{background:var(--accent);color:#053a35}
    .btn-alt{background:transparent;color:#cdeae6;border:1px solid rgba(255,255,255,0.04)}
    .meta{font-size:13px;color:var(--muted);margin-top:12px}
    .aside-hero{padding:18px}
    .stat{display:flex;flex-direction:column;gap:6px;margin-bottom:10px}
    .stat strong{color:var(--accent)}

    section{margin-top:28px}
    .grid-2{display:grid;grid-template-columns:1fr 340px;gap:22px}
    .reveal{opacity:0;transform:translateY(14px) scale(0.995);transition:opacity 560ms cubic-bezier(.2,.9,.3,1),transform 560ms cubic-bezier(.2,.9,.3,1)}
    .reveal.in-view{opacity:1;transform:none}
    .micro{display:flex;flex-direction:column;gap:10px}
    .micro li{background:var(--glass);padding:12px;border-radius:8px;font-size:14px}
    footer{max-width:var(--maxw);margin:40px auto 80px;padding:0 20px;color:var(--muted);font-size:13px}
    .notice{background:linear-gradient(180deg,rgba(122,211,200,0.05),transparent);padding:12px;border-radius:8px;border:1px solid rgba(122,211,200,0.06);color:#dff8f4}
    .contrad{font-size:13px;color:#ffebee;background:linear-gradient(180deg,rgba(255,235,238,0.03),transparent);padding:12px;border-radius:8px;margin-top:12px}
    .faq-toggle{cursor:pointer}
    @media(max-width:880px){.hero{grid-template-columns:1fr;}.grid-2{grid-template-columns:1fr}.navlinks{display:none}}
  </style>
</head>
<body>
  <header>
    <nav>
      <div class="brand">{{BUSINESS_NAME}}</div>
      <div class="navlinks">
        <a href="index.html">Gatherings</a>
        <a href="events.html">Schedule</a>
        <a href="private-sessions.html">Private</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">About</a>
        <a href="faq.html">FAQs</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Connect</a>
      </div>
    </nav>
  </header>

  <main class="container">
    <section class="hero card reveal" aria-labelledby="about-hero">
      <div>
        <h1 id="about-hero">How we shape the hour</h1>
        <p class="lead">We design sound-led gatherings that act as a gentle structural support for attention and rest. Small group sessions, occasional intensives, and private sound work tuned to daily life.</p>
        <div class="actions">
          <button class="btn btn-primary" id="tryNowBtn">Try the mini-exercise</button>
          <a class="btn btn-alt" href="book.html">Reserve a spot</a>
        </div>
        <div class="meta">Sessions in a calm studio in {{CITY}}, {{STATE}} — questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
      </div>
      <aside class="aside-hero">
        <div class="stat"><strong>Small groups</strong><span class="muted">Up to 12 people</span></div>
        <div class="stat"><strong>Sound palette</strong><span class="muted">Tuned bowls, breath cues, silence</span></div>
        <div class="stat"><strong>Session length</strong><span class="muted">60 - 90 minutes</span></div>
      </aside>
    </section>

    <section class="card reveal" aria-labelledby="why-title">
      <h2 id="why-title">A practical framework</h2>
      <div class="grid-2">
        <div>
          <p>We think of sessions as composed layers: orientation (what you bring), guided support (breathing and prompts), and tonal field (sound that holds attention). Each element is simple — the design is in how they're sequenced.</p>
          <p class="meta">You’ll leave with one clear practice you can use at home: a short intention + a breath pattern + a two-note sonic anchor.</p>
        </div>
        <aside>
          <div class="notice">Program names: Resonance Sessions (weekly), Focus Arc (multi-week), and One-to-One Harmonies (private). Pricing and details are on the booking page.</div>
        </aside>
      </div>
    </section>

    <section class="card reveal" aria-labelledby="diagnostic-title">
      <h3 id="diagnostic-title">Who benefits</h3>
      <p>People who want a reliable container for slowing down without rituals that feel loud. These gatherings work whether you come with a recent stressor, a curiosity, or just a need to re-center.</p>
      <ul class="micro">
        <li>Shift from doing to sensing in 15–25 minutes</li>
        <li>Practice a brief anchoring routine to use anywhere</li>
        <li>Find clarity on a small decision through intention setting</li>
      </ul>
    </section>

    <section class="card reveal" aria-labelledby="micro-title">
      <h3 id="micro-title">Small steps to integrate</h3>
      <ol class="micro">
        <li>Three-breath reset: inhale fully, hold two counts, exhale three.</li>
        <li>Evening 2-minute note: place a hand, listen to your skin, write one word.</li>
        <li>Weekly check-in: what did sound show you about attention?</li>
      </ol>
    </section>

    <section class="card reveal" aria-labelledby="pricing-title">
      <h3 id="pricing-title">How we frame value</h3>
      <p>Instead of "packages," we offer participation frames: drop-in, commitment cycle, and private deep-dive. Each is priced to reflect access, preparation, and the time we hold together.</p>
      <ul>
        <li>Drop-in — single session, flexible dates.</li>
        <li>Commitment cycle — 4 sessions, recommended cadence once weekly.</li>
        <li>Private deep-dive — 75-minute one-on-one format.</li>
      </ul>
      <div style="margin-top:12px"><a class="btn btn-primary" href="pricing.html">See detailed rates</a></div>
    </section>

    <section class="card reveal" aria-labelledby="contrad-title">
      <h3 id="contrad-title">Contraindications & safety</h3>
      <p class="contrad">If you have a history of seizure disorder, uncontrolled hypertension, recent head injury, pregnancy concerns, or are under psychiatric care with active medication changes, please consult your physician before attending. Vibrational work and resonant sound can feel intense for some people; if you use a pacemaker or are sensitive to sound, contact us for guidance.</p>
    </section>

    <section class="card reveal" aria-labelledby="reach-title">
      <h3 id="reach-title">Ready to meet the hour?</h3>
      <p>Book a trial session or request a private consultation. If this is your first time, we recommend the Drop-in or a Private Harmonies meeting.</p>
      <div class="actions"><a class="btn btn-primary" href="book.html">Reserve a trial</a><a class="btn btn-alt" href="contact.html">Ask a question</a></div>
    </section>
  </main>

  <footer>
    <div style="max-width:var(--maxw);margin:0 auto">© <span id="yr"></span> {{BUSINESS_NAME}} — <span style="color:var(--muted)">Portions of the work are experiential; results vary.</span></div>
  </footer>

  <!-- Guided exercise modal (Try it now) -->
  <div id="exerciseModal" aria-hidden="true" style="position:fixed;inset:0;display:none;align-items:center;justify-content:center;padding:20px;z-index:90">
    <div role="dialog" aria-modal="true" aria-label="Mini guided practice" style="max-width:720px;width:100%;background:linear-gradient(180deg,#021919, #031718);border-radius:12px;padding:20px;border:1px solid rgba(255,255,255,0.04);box-shadow:0 10px 40px rgba(0,0,0,0.6);color:#e6fbf8">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><strong>Try: 6-minute reset</strong><button id="closeModal" aria-label="Close" style="background:transparent;border:none;color:#cdeae6;cursor:pointer">✕</button></div>
      <div id="stage" style="display:grid;grid-template-columns:1fr 160px;gap:18px;align-items:center">
        <div>
          <p id="stageText">We’ll move through three short steps: breathe, journal, set an intention. Play along — use headphones if you like.</p>
          <div style="margin-top:10px">
            <button id="startBtn" class="btn btn-primary">Begin — 6 minutes</button>
            <button id="nextBtn" class="btn btn-alt" style="display:none">Next</button>
          </div>
        </div>
        <div style="display:flex;flex-direction:column;align-items:center;gap:12px">
          <svg id="breathCircle" width="120" height="120" viewBox="0 0 120 120" aria-hidden="true">
            <defs>
              <linearGradient id="g1" x1="0" x2="1">
                <stop offset="0" stop-color="#47d3bf" />
                <stop offset="1" stop-color="#6ee0d2" />
              </linearGradient>
            </defs>
            <circle cx="60" cy="60" r="44" stroke="rgba(255,255,255,0.06)" stroke-width="10" fill="none"></circle>
            <circle id="pulse" cx="60" cy="60" r="32" fill="url(#g1)" opacity="0.12"></circle>
          </svg>
          <div style="font-size:13px;color:#cfeee9;text-align:center">Follow the prompts — breaths are counted on-screen.</div>
        </div>
      </div>
    </div>
  </div>

  <script>
    // accessibility: respect reduced motion
    const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    // reveal on scroll
    (function(){
      const reveals = document.querySelectorAll('.reveal');
      if(prefersReduced){reveals.forEach(el=>el.classList.add('in-view'));return}
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');obs.unobserve(e.target)}}),{threshold:0.12}
      );
      reveals.forEach(r=>obs.observe(r));
    })();

    // modal and guided exercise
    const modal = document.getElementById('exerciseModal');
    const tryBtn = document.getElementById('tryNowBtn');
    const closeBtn = document.getElementById('closeModal');
    const startBtn = document.getElementById('startBtn');
    const nextBtn = document.getElementById('nextBtn');
    const stageText = document.getElementById('stageText');
    const pulse = document.getElementById('pulse');
    let step = 0;let timer=null;let counts=0;

    function openModal(){ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); document.body.style.overflow='hidden'; step=0; prepareStep(); }
    function closeModalFunc(){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); document.body.style.overflow=''; clearInterval(timer); resetVisual(); }

    function resetVisual(){ pulse.style.transform='scale(1)'; pulse.style.opacity='0.12' }

    function prepareStep(){
      startBtn.style.display='inline-flex'; nextBtn.style.display='none';
      if(step===0){ stageText.textContent='Step 1 — Breathing: 3 rounds. Inhale 4s, hold 2s, exhale 6s. Follow the circle.' }
      if(step===1){ stageText.textContent='Step 2 — Journaling: 90 seconds. Write a short line about what you noticed.' }
      if(step===2){ stageText.textContent='Step 3 — Intention: Choose one small action for today. State it aloud or write it.' }
    }

    function runBreath(){ if(prefersReduced){counts=0;setTimeout(()=>{completeStep()},800)} else {
      let phases = ['inhale','hold','exhale'];let phaseDur=[4,2,6];let p=0;let sub=0;stageText.textContent='Breathing — follow the circle';
      timer = setInterval(()=>{
        sub++;
        const total = phaseDur[p];
        const scale = 1 + (0.45 * ( (p===0)? (sub/total) : (p===2? (1 - (sub/total)) : 0) ));
        pulse.style.transform = `scale(${scale})`;
        pulse.style.opacity = `${0.12 + (0.65*(sub/total))}`;
        if(sub>=total){sub=0;p++;if(p>=phases.length){p=0;counts++; if(counts>=3){clearInterval(timer);completeStep()}}}
      },1000);
    }}

    function runJournal(){ stageText.textContent='Journaling — a 90s prompt: "One small change I can try this week is..."';
      let t=90; nextBtn.style.display='none'; startBtn.style.display='none';
      timer = setInterval(()=>{t--; pulse.style.transform=`scale(${1 + 0.03*Math.sin(Date.now()/300)})`; if(t<=0){clearInterval(timer);completeStep()} },1000);
    }

    function runIntention(){ stageText.textContent='Intention — state one clear step. Hold it for 30 seconds.';
      let t=30; timer=setInterval(()=>{t--; if(t<=0){clearInterval(timer);completeStep()} },1000);
    }

    function completeStep(){ step++; resetVisual(); if(step>2){stageText.textContent='Complete — thank you. When you close, a short suggestion will be copied into your clipboard.'; navigator.clipboard && navigator.clipboard.writeText('Today: take one small step toward presence.'); startBtn.style.display='none'; nextBtn.textContent='Close'; nextBtn.style.display='inline-flex'; nextBtn.onclick=closeModalFunc; } else {startBtn.style.display='none'; nextBtn.style.display='inline-flex'; nextBtn.onclick=advanceStep}}

    function advanceStep(){ nextBtn.style.display='none'; if(step===1) runJournal(); if(step===2) runIntention(); if(step===0) runBreath(); }

    tryBtn && tryBtn.addEventListener('click',()=>openModal()); closeBtn.addEventListener('click',closeModalFunc);
    startBtn && startBtn.addEventListener('click',()=>{ startBtn.style.display='none'; if(step===0) runBreath(); if(step===1) runJournal(); if(step===2) runIntention(); });

    // keyboard escape
    document.addEventListener('keydown',e=>{if(e.key==='Escape' && modal.style.display==='flex') closeModalFunc()});

    // small helper: set year
    document.getElementById('yr').textContent = new Date().getFullYear();

  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQs — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071617;--muted:#98b6b3;--accent:#6fe0cf;--card:#071919;--maxw:980px}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#eafaf6;background:linear-gradient(0deg,#041618,#072120)}
    header{padding:14px 20px;border-bottom:1px solid rgba(255,255,255,0.03);background:rgba(0,0,0,0.08)}
    nav{max-width:var(--maxw);margin:0 auto;display:flex;align-items:center;gap:14px}
    .brand{color:var(--accent);font-weight:700}
    .navlinks{margin-left:auto;display:flex;gap:12px}
    .navlinks a{color:#dffaf4;text-decoration:none;font-size:14px;padding:8px;border-radius:8px}
    main{max-width:var(--maxw);margin:28px auto;padding:0 20px}
    .hero{display:flex;flex-direction:column;gap:10px;padding:18px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border:1px solid rgba(255,255,255,0.03)}
    h1{margin:0 0 4px}
    .lead{color:var(--muted);margin:0}
    .faq-list{margin-top:18px;display:grid;gap:10px}
    .faq-item{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px;border:1px solid rgba(255,255,255,0.02)}
    .question{display:flex;justify-content:space-between;align-items:center;cursor:pointer}
    .answer{max-height:0;overflow:hidden;transition:max-height 420ms ease;padding-top:0}
    .answer.open{padding-top:10px;max-height:400px}
    .small{font-size:13px;color:var(--muted)}
    .try-row{display:flex;gap:8px;margin-top:12px}
    .btn{padding:8px 12px;border-radius:8px;border:none;cursor:pointer}
    .btn-primary{background:var(--accent);color:#062c2a;font-weight:700}
    .reveal{opacity:0;transform:translateY(14px);transition:opacity 560ms cubic-bezier(.2,.9,.3,1),transform 560ms cubic-bezier(.2,.9,.3,1)}
    .reveal.in-view{opacity:1;transform:none}
    footer{max-width:var(--maxw);margin:30px auto;color:var(--muted);font-size:13px}
  </style>
</head>
<body>
  <header>
    <nav>
      <div class="brand">{{BUSINESS_NAME}}</div>
      <div class="navlinks">
        <a href="index.html">Gatherings</a>
        <a href="events.html">Schedule</a>
        <a href="private-sessions.html">Private</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">About</a>
        <a href="faq.html">FAQs</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Connect</a>
      </div>
    </nav>
  </header>

  <main>
    <section class="hero reveal">
      <h1>Questions answered</h1>
      <p class="lead">Practical notes for attending, preparing, and understanding safety. If something is missing, reach out — we’ll reply within two business days.</p>
      <div class="try-row"><button id="tryNowBtn" class="btn btn-primary">Try the mini-practice</button><a class="btn" href="book.html" style="background:transparent;border:1px solid rgba(255,255,255,0.03);color:#dffaf4">Book a trial</a></div>
    </section>

    <section style="max-width:900px;margin:18px auto;padding:0 20px">
      <div class="faq-list">
        <div class="faq-item reveal">
          <div class="question"><div><strong>What should I bring?</strong><div class="small">Bring a mat, blanket, and something to cover your eyes if you like. We provide bolsters.</div></div><div class="faq-toggle" aria-hidden>▸</div></div>
          <div class="answer"><p class="small">Comfort is the priority. Layer clothing for temperature changes, and avoid heavy perfumes.</p></div>
        </div>

        <div class="faq-item reveal">
          <div class="question"><div><strong>Will the sounds be loud?</strong><div class="small">No — the session uses tonal instruments at comfortable listening levels.</div></div><div class="faq-toggle">▸</div></div>
          <div class="answer"><p class="small">The design favors subtle resonance and silence. If you have hearing sensitivity, tell us before the session and we will adapt placement and levels.</p></div>
        </div>

        <div class="faq-item reveal">
          <div class="question"><div><strong>How early should I arrive?</strong><div class="small">Arrive 10 minutes early for settling and orientation.</div></div><div class="faq-toggle">▸</div></div>
          <div class="answer"><p class="small">We close doors once the session begins to preserve the field. Late arrivals may be admitted quietly at a suitable break.</p></div>
        </div>

        <div class="faq-item reveal">
          <div class="question"><div><strong>Contraindications?</strong><div class="small">See the full safety guidance and consult your clinician when in doubt.</div></div><div class="faq-toggle">▸</div></div>
          <div class="answer"><p class="small">If you have a cardiac device, seizure history, are pregnant with concerns, or under active psychiatric medication adjustments, consult your provider first. Contact us if unsure.</p></div>
        </div>

        <div class="faq-item reveal">
          <div class="question"><div><strong>Can I record or photograph?</strong><div class="small">We ask that sessions remain device-free for presence.</div></div><div class="faq-toggle">▸</div></div>
          <div class="answer"><p class="small">No recordings, please, unless part of a pre-arranged private session. Respect others' privacy.</p></div>
        </div>
      </div>
    </section>

    <section style="max-width:900px;margin:18px auto;padding:0 20px" class="reveal">
      <h3>Still curious?</h3>
      <p class="small">Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a>. We can suggest the right format for your needs.</p>
    </section>
  </main>

  <footer>
    <div style="max-width:var(--maxw);margin:20px auto;padding:0 20px;color:var(--muted)">© <span id="yr"></span> {{BUSINESS_NAME}} — Responsible guidance provided; always prioritize medical advice.</div>
  </footer>

  <!-- Guided exercise modal (reused) -->
  <div id="exerciseModal" aria-hidden="true" style="position:fixed;inset:0;display:none;align-items:center;justify-content:center;padding:20px;z-index:90">
    <div role="dialog" aria-modal="true" style="max-width:640px;width:100%;background:#022020;border-radius:10px;padding:18px;border:1px solid rgba(255,255,255,0.03);color:#dff9f3">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><strong>Mini practice — 3 steps</strong><button id="closeModal" style="background:transparent;border:none;color:#cdeae6;cursor:pointer">✕</button></div>
      <p id="stageText">Use the button to begin; the exercise guides breathing, a quick note, and a one-line intention.</p>
      <div style="display:flex;gap:8px;margin-top:8px"><button id="startBtn" class="btn btn-primary">Start</button><button id="nextBtn" class="btn" style="display:none">Next</button></div>
    </div>
  </div>

  <script>
    // reduced motion awareness
    const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    // reveal elements
    (function(){
      const items = document.querySelectorAll('.reveal');
      if(prefersReduced){items.forEach(i=>i.classList.add('in-view'));return}
      const obs = new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');obs.unobserve(e.target)}}),{threshold:0.12});
      items.forEach(it=>obs.observe(it));
    })();

    // FAQ toggles
    document.querySelectorAll('.faq-item').forEach(item=>{
      const q = item.querySelector('.question'); const a = item.querySelector('.answer'); q.addEventListener('click',()=>{ const open = a.classList.toggle('open'); q.querySelector('.faq-toggle').textContent = open ? '▾' : '▸'; });
    });

    // guided exercise (compact)
    const tryBtn = document.getElementById('tryNowBtn');
    const modal = document.getElementById('exerciseModal');
    const closeBtn = document.getElementById('closeModal');
    const startBtn = document.getElementById('startBtn');
    const nextBtn = document.getElementById('nextBtn');
    const stageText = document.getElementById('stageText');
    let step=0, timer=null;
    function openModal(){ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); step=0; stageText.textContent='Step 1: breathe'; startBtn.style.display='inline-block'; nextBtn.style.display='none'; }
    function closeModal(){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); clearInterval(timer) }
    tryBtn.addEventListener('click',openModal); closeBtn.addEventListener('click',closeModal);
    startBtn.addEventListener('click',()=>{ startBtn.style.display='none'; runPhase();});
    function runPhase(){ if(step===0){ if(prefersReduced){ setTimeout(()=>advance(),700) } else { let t=12; stageText.textContent='Breathing — 3 cycles'; timer=setInterval(()=>{ t--; if(t<=0){clearInterval(timer); advance()} },1000) } }
      else if(step===1){ stageText.textContent='Write a single line — 90s'; let t=90; timer=setInterval(()=>{t--; if(t<=0){clearInterval(timer); advance()} },1000)}
      else if(step===2){ stageText.textContent='Say one intention — 30s'; let t=30; timer=setInterval(()=>{t--; if(t<=0){clearInterval(timer); advance()} },1000)} }
