{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071919;--card:#071b1b;--muted:#9fc2bd;--accent:#5fe2c9;--maxw:980px}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#e8fbf7;background:linear-gradient(180deg,#041818,#062121)}
    header{padding:12px 18px;border-bottom:1px solid rgba(255,255,255,0.03)}
    nav{max-width:var(--maxw);margin:0 auto;display:flex;align-items:center}
    .brand{color:var(--accent);font-weight:700}
    .navlinks{margin-left:auto;display:flex;gap:12px}
    .navlinks a{color:#dffdf9;text-decoration:none}
    main{max-width:var(--maxw);margin:24px auto;padding:0 20px}
    .layout{display:grid;grid-template-columns:1fr 320px;gap:22px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    h1{margin:0 0 8px}
    label{display:block;margin-top:10px;font-size:14px;color:var(--muted)}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:#e6fbf8}
    .btn{padding:10px 12px;border-radius:9px;border:none;cursor:pointer;margin-top:12px}
    .btn-primary{background:var(--accent);color:#033533;font-weight:700}
    .session-list{display:flex;flex-direction:column;gap:8px}
    .session{padding:10px;border-radius:10px;background:rgba(0,0,0,0.16);display:flex;justify-content:space-between;align-items:center}
    .price{font-weight:700;color:var(--accent)}
    .summary{font-size:14px;color:var(--muted);margin-top:10px}
    .reveal{opacity:0;transform:translateY(14px);transition:opacity 560ms cubic-bezier(.2,.9,.3,1),transform 560ms cubic-bezier(.2,.9,.3,1)}
    .reveal.in-view{opacity:1;transform:none}
    @media(max-width:880px){.layout{grid-template-columns:1fr}.navlinks{display:none}}
  </style>
</head>
<body>
  <header>
    <nav>
      <div class="brand">{{BUSINESS_NAME}}</div>
      <div class="navlinks">
        <a href="index.html">Gatherings</a>
        <a href="events.html">Schedule</a>
        <a href="private-sessions.html">Private</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">About</a>
        <a href="faq.html">FAQs</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Connect</a>
      </div>
    </nav>
  </header>

  <main>
    <div class="layout">
      <div>
        <section class="card reveal">
          <h1>Reserve a session</h1>
          <p class="small">Choose a format and share a few details. We'll follow up within 48 hours to confirm availability.</p>

          <form id="bookForm">
            <label for="name">Your name</label>
            <input id="name" name="name" required>
            <label for="email">Email</label>
            <input id="email" name="email" type="email" required>
            <label for="phone">Phone</label>
            <input id="phone" name="phone" type="tel">

            <label for="sessionType">Session type</label>
            <select id="sessionType" name="sessionType">
              <option value="resonance">Resonance Session — group (60m)</option>
              <option value="commitment">Commitment Cycle — 4-session set</option>
              <option value="private">Private Harmonics — one-on-one (75m)</option>
            </select>

            <label for="datePref">Preferred date or range</label>
            <input id="datePref" name="datePref" placeholder="e.g. March weekends, or 2026-04-12">

            <label for="notes">Notes (contraindications, accessibility needs)</label>
            <textarea id="notes" name="notes" rows="3" placeholder="Tell us about any medical notes or concerns"></textarea>

            <div class="summary">We ask participants to confirm they have read the safety guidance. If in doubt, contact your clinician.</div>

            <button class="btn btn-primary" type="submit">Request reservation</button>
          </form>

          <div id="response" style="display:none;margin-top:12px;padding:10px;border-radius:8px;background:rgba(95,226,201,0.06);border:1px solid rgba(95,226,201,0.08);color:#cffbf5"></div>
        </section>

        <section class="card reveal">
          <h3>Booking notes</h3>
          <ul>
            <li class="small">Drop-in seats are limited; Commitment Cycles have priority scheduling.</li>
            <li class="small">If you need to cancel, please notify us 48 hours in advance.</li>
            <li class="small">For private work, specify your goals briefly in the notes.</li>
          </ul>
        </section>
      </div>

      <aside>
        <div class="card reveal">
          <h3>Available frames</h3>
          <div class="session-list">
            <div class="session"><div>Resonance — drop-in</div><div class="price">$28</div></div>
            <div class="session"><div>Commitment Cycle — 4x</div><div class="price">$100</div></div>
            <div class="session"><div>Private Harmonics</div><div class="price">$160</div></div>
          </div>
          <div style="margin-top:10px" class="small">Prices reflect preparation and dedicated time. Packages may include email follow-up.</div>
        </div>

        <div class="card reveal" style="margin-top:12px">
          <h4>Quick availability</h4>
          <p class="small">We typically host sessions on weeknights and occasional weekend mornings. If you have a day preference, write it in the date field.</p>
        </div>
      </aside>
    </div>
  </main>

  <footer style="max-width:var(--maxw);margin:26px auto;padding:0 20px;color:var(--muted)">© <span id="yr"></span> {{BUSINESS_NAME}} — For medical questions, consult a clinician before booking.</footer>

  <!-- lightweight reveal script + form handling + Try-it modal -->
  <div id="exerciseModal" aria-hidden="true" style="position:fixed;inset:0;display:none;align-items:center;justify-content:center;padding:20px;z-index:90">
    <div role="dialog" aria-modal="true" style="max-width:640px;width:100%;background:#022423;border-radius:10px;padding:18px;border:1px solid rgba(255,255,255,0.03);color:#ddfbf5">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><strong>Micro practice</strong><button id="closeModal" style="background:transparent;border:none;color:#cdeae6;cursor:pointer">✕</button></div>
      <p id="stageText">Prepare: a chair or mat. When ready, press Start to be guided through a brief breath, note, and intention.</p>
      <div style="display:flex;gap:8px;margin-top:8px"><button id="startBtn" class="btn btn-primary">Start</button><button id="nextBtn" class="btn" style="display:none">Next</button></div>
    </div>
  </div>

  <script>
    const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    // reveal
    (function(){ const nodes = document.querySelectorAll('.reveal'); if(prefersReduced){nodes.forEach(n=>n.classList.add('in-view'));return} const obs = new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');obs.unobserve(e.target)}}),{threshold:0.12}); nodes.forEach(n=>obs.observe(n));})();

    // form handling (no external submission)
    const form = document.getElementById('bookForm'); const resp = document.getElementById('response');
    form.addEventListener('submit',e=>{ e.preventDefault(); const data = new FormData(form); const obj = {}; data.forEach((v,k)=>obj[k]=v); // simulate async
      resp.style.display='block'; resp.textContent='Sending your request…'; setTimeout(()=>{ resp.textContent = `Thanks, ${obj.name || 'guest'} — we received your request and will reply at ${obj.email || 'your email'}. If urgent, call ${'{'}{PHONE}{'}'}.`; form.reset(); },900);
    });

    // guided exercise modal (shared logic similar to other pages)
    const tryNowTriggers = document.querySelectorAll('a[href="book.html"], #startBtn'); // include start on modal
    const modal = document.getElementById('exerciseModal');
    const closeBtn = modal.querySelector('#closeModal');
    const startBtn = modal.querySelector('#startBtn');
    const nextBtn = modal.querySelector('#nextBtn');
    const stageText = modal.querySelector('#stageText');
    let step=0, timer=null;
    // open when user arrives on this page via nav or clicks elsewhere - provide a visible Try it trigger too
    const pageTry = document.createElement('button'); pageTry.textContent='Try mini-practice'; pageTry.className='btn btn-primary'; pageTry.style.position='fixed'; pageTry.style.right='18px'; pageTry.style.bottom='18px'; pageTry.style.zIndex='80'; document.body.appendChild(pageTry);
    function openModal(){ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); step=0; stageText.textContent='Step 1 — breathing'; startBtn.style.display='inline-block'; nextBtn.style.display='none'; }
    pageTry.addEventListener('click',openModal);
    closeBtn.addEventListener('click',()=>{ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); clearInterval(timer) });
    startBtn.addEventListener('click',()=>{ startBtn.style.display='none'; runPhase() });
    function runPhase(){ if(step===0){ if(prefersReduced){ setTimeout(()=>complete(),700) } else { let t=10; stageText.textContent='Breathing — follow a gentle count'; timer=setInterval(()=>{ t--; if(t<=0){clearInterval(timer); complete()} },1000) } }
      else if(step===1){ let t=80; stageText.textContent='Quick journaling — 80s'; timer=setInterval(()=>{t--; if(t<=0){clearInterval(timer); complete()} },1000) }
      else if(step===2){ let t=25; stageText.textContent='State one clear intention — 25s'; timer=setInterval(()=>{t--; if(t<=0){clearInterval(timer); complete()} },1000) } }
    function complete(){ step++; if(step>2){ stageText.textContent='Complete — close this window or continue booking.'; nextBtn.style.display='inline-block'; nextBtn.textContent='Close'; nextBtn.onclick=(()=>{ modal.style.display='none'; modal.setAttribute('aria-hidden','true') }) } else { nextBtn.style.display='inline-block'; nextBtn.textContent='Next'; nextBtn.onclick=(()=>{ nextBtn.style.display='none'; runPhase() }) } }

    // small helper: set year
    document.getElementById('yr').textContent = new Date().getFullYear();
  </script>
</body>
</html>"} 
